<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue';
import { api, ApiError } from '../api';import { useWorkspace, useSession, type WorkTab } from '../stores';import PersonDrawer from '../components/PersonDrawer.vue';import OrgChartNode from '../components/OrgChartNode.vue';import { buildChart } from '../../../lib/workspace/organization-rules';import { descendants, unitTypes, managerRoles, canMoveUnit } from '../organization';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace(),session=useSession();
const units=ref<any[]>([]),caps=ref<any>({}),version=ref(''),error=ref(''),message=ref(''),loading=ref(false),search=ref(''),type=ref(''),inactive=ref(false),selected=ref(''),collapsed=ref(new Set<string>()),editing=ref(false),conflict=ref(false),zoom=ref(100),viewport=ref<HTMLElement|null>(null);
let baseline='',requestId='',pendingKey='';
const dragging=ref('');const viewMode=ref<'tree'|'chart'>('tree'),drawerUser=ref<any>(null);
const chart=computed(()=>buildChart(units.value,inactive.value));
const dim=computed(()=>search.value.trim()||type.value?matches.value:null);
const canDrawer=computed(()=>current.value?.type==='department');
function collapseTwo(){collapsed.value=new Set(units.value.filter(u=>u.parent_id!==null).map(u=>u.id));}
function dragStart(event:DragEvent,id:string){if(!editing.value||props.tab.busy||conflict.value)return;dragging.value=id;event.dataTransfer?.setData('text/plain',id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move';}
function dropUnit(parent:string|null){const id=dragging.value;dragging.value='';if(!editing.value||props.tab.busy||conflict.value)return;if(!canMoveUnit(units.value,id,parent)){error.value='不可移到自己、下層或停用單位；公司固定為根節點。';return;}units.value.find(u=>u.id===id).parent_id=parent;collapsed.value=new Set([...collapsed.value].filter(x=>x!==parent));error.value='';}

const hierarchy=()=>JSON.stringify(units.value.map(u=>({id:u.id,parent_id:u.parent_id,sort_order:u.sort_order})));
watch(units,()=>{if(editing.value)props.tab.dirty=hierarchy()!==baseline;},{deep:true,flush:'sync'});
async function load(){if(props.tab.dirty)return;loading.value=true;error.value='';message.value='';try{const d=await api('organization');units.value=d.units;caps.value=d.capabilities;version.value=d.version;baseline=hierarchy();editing.value=false;conflict.value=false;if(!units.value.some(u=>u.id===selected.value))selected.value=units.value[0]?.id||'';}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
const matches=computed(()=>new Set(units.value.filter(u=>(inactive.value||u.status==='active')&&(!type.value||u.type===type.value)&&(!search.value.trim()||[u.code,u.name,u.short_name,...u.members.map((m:any)=>m.user?.full_name),...u.managers.map((m:any)=>m.user?.full_name)].some(v=>String(v||'').toLowerCase().includes(search.value.trim().toLowerCase())))).map(u=>u.id)));
const rows=computed(()=>{
 const filtered=Boolean(search.value.trim()||type.value);const included=new Set(matches.value);
 for(const id of [...included]){let u=units.value.find(u=>u.id===id);const seen=new Set<string>();while(u?.parent_id&&!seen.has(u.parent_id)){seen.add(u.parent_id);included.add(u.parent_id);u=units.value.find(x=>x.id===u.parent_id);}}
 const output:{unit:any;depth:number;children:boolean;context:boolean}[]=[];const seen=new Set<string>();
 function walk(parent:string|null,depth:number){for(const u of units.value.filter(u=>u.parent_id===parent).sort((a,b)=>a.sort_order-b.sort_order||a.code.localeCompare(b.code))){if(seen.has(u.id)||!included.has(u.id))continue;seen.add(u.id);output.push({unit:u,depth,children:units.value.some(x=>x.parent_id===u.id&&included.has(x.id)),context:!matches.value.has(u.id)});if(filtered||!collapsed.value.has(u.id))walk(u.id,depth+1);}}
 walk(null,0);return output;
});
watch(()=>work.organizationRevision,()=>{if(props.tab.busy||loading.value)return;if(!props.tab.dirty)void load();else message.value='其他工作頁已更新組織資料；目前層級草稿仍保留，儲存前請重新核對。';});
const current=computed(()=>units.value.find(u=>u.id===selected.value));
const descendantCount=computed(()=>{if(!current.value)return 0;const ids=descendants(units.value,current.value.id);return new Set(units.value.filter(u=>ids.has(u.id)).flatMap(u=>u.members.map((m:any)=>m.user_id))).size;});
function toggle(id:string){const next=new Set(collapsed.value);if(next.has(id))next.delete(id);else next.add(id);collapsed.value=next;}
function open(mode='basic',create=false){const tab=work.open('organization-editor','',create?undefined:selected.value);tab.payload={mode,parentId:create?selected.value:null};tab.title=create?'新增組織單位':`${mode==='members'?'成員':mode==='managers'?'主管':'組織'} · ${current.value?.name}`;}
function parentOptions(u:any){const excluded=descendants(units.value,u.id);return units.value.filter(x=>!excluded.has(x.id)&&(x.status==='active'||x.id===u.parent_id));}
function discard(){if(!baseline)return;const original=JSON.parse(baseline);for(const u of units.value){const row=original.find((x:any)=>x.id===u.id);if(row){u.parent_id=row.parent_id;u.sort_order=row.sort_order;}}props.tab.dirty=false;editing.value=false;conflict.value=false;}
async function save(){if(!editing.value||!caps.value.hierarchy||props.tab.busy||conflict.value)return false;props.tab.busy=true;error.value='';const original=JSON.parse(baseline);const updates=units.value.filter(u=>{const old=original.find((x:any)=>x.id===u.id);return old?.parent_id!==u.parent_id||old?.sort_order!==u.sort_order;}).map(u=>({id:u.id,parent_id:u.parent_id,sort_order:u.sort_order}));const key=JSON.stringify(updates);if(key!==pendingKey){pendingKey=key;requestId=crypto.randomUUID();}try{await api('organization',{method:'POST',body:JSON.stringify({operation:'hierarchy',data:{updates},requestId,expected:version.value})});work.organizationRevision++;props.tab.dirty=false;editing.value=false;pendingKey='';requestId='';await load();message.value=error.value?'層級已儲存，請重新載入確認':'組織層級已儲存';return true;}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.status===409;return false;}finally{props.tab.busy=false;}}
let pan:{x:number;y:number;left:number;top:number}|null=null;
function panStart(e:PointerEvent){if((e.target as HTMLElement).closest('button,input,select,a,label,[draggable]'))return;const el=viewport.value!;pan={x:e.clientX,y:e.clientY,left:el.scrollLeft,top:el.scrollTop};el.setPointerCapture(e.pointerId);}
function panMove(e:PointerEvent){if(pan&&viewport.value){viewport.value.scrollLeft=pan.left+pan.x-e.clientX;viewport.value.scrollTop=pan.top+pan.y-e.clientY;}}
props.tab.save=save;props.tab.discard=async()=>discard();onMounted(load);onBeforeUnmount(()=>{delete props.tab.save;delete props.tab.discard;});
</script>
<template>
<header class="page-heading"><div><p class="eyebrow">組織與門市 / 公司組織</p><h1>公司組織</h1></div><div class="actions"><button :disabled="loading||tab.busy||tab.dirty" @click="load">重新載入</button><button v-if="caps.create" class="primary" :disabled="loading||tab.busy" @click="open('basic',true)">新增組織單位</button></div></header>
<p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading" role="status">載入組織架構…</p>
<div class="filters"><label>搜尋單位或人員<input v-model="search" placeholder="單位名稱、代碼、成員或主管"></label><label>類型<select v-model="type"><option value="">全部類型</option><option v-for="(label,key) in unitTypes" :value="key">{{label}}</option></select></label><label class="check"><input type="checkbox" v-model="inactive">包含停用單位</label></div>
<div class="toolbar"><button @click="collapsed=new Set()">全部展開</button><button @click="collapsed=new Set(units.map(u=>u.id))">收合至第一層</button><button @click="collapseTwo">展開至第二層</button><span class="view-switch" role="group" aria-label="顯示模式"><button data-testid="view-tree" :aria-pressed="viewMode==='tree'" :class="{primary:viewMode==='tree'}" @click="viewMode='tree'">樹狀</button><button data-testid="view-chart" :aria-pressed="viewMode==='chart'" :class="{primary:viewMode==='chart'}" :disabled="editing" @click="viewMode='chart'">組織圖</button></span><label v-if="viewMode==='tree'">縮放<select v-model.number="zoom"><option v-for="z in [75,100,125,150]" :value="z">{{z}}%</option></select></label><button v-if="viewMode==='tree'" @click="zoom=100;viewport?.scrollTo({top:0,left:0})">重設視圖</button><button v-if="caps.hierarchy&&!editing&&viewMode==='tree'" :disabled="loading||!units.length" @click="editing=true;baseline=hierarchy()">調整層級</button><template v-if="editing"><button :disabled="tab.busy" @click="discard">取消調整</button><button class="primary" :disabled="!tab.dirty||tab.busy||conflict" @click="save">{{tab.busy?'儲存中…':'儲存層級'}}</button></template></div>
<p v-if="editing" class="notice">可拖曳「移動」至上層單位，或使用上層選單與排序後整批儲存；公司固定為根節點。搜尋不會移除未顯示單位的調整。</p><p v-if="conflict" class="notice error">資料已更新，請記下目前調整，再取消調整並重新載入核對。</p>
<div v-if="editing" class="root-drop" @dragover.prevent @drop.prevent="dropUnit(null)">移至最上層：將單位拖放至此處</div><div class="organization-layout"><section v-if="viewMode==='chart'" class="tree-viewport chart-viewport" data-testid="org-chart" aria-label="組織圖（唯讀）" tabindex="0"><p class="notice">組織圖為唯讀；調整層級、成員與主管請切回樹狀模式。</p><p v-if="!chart.length">{{units.length?'沒有符合條件的單位':'尚無組織單位。'}}</p><ul class="chart-root"><OrgChartNode v-for="node in chart" :key="node.unit.id" :node="node" :selected="selected" :dim="dim" @select="selected=$event"/></ul></section><section v-else ref="viewport" class="tree-viewport" aria-label="組織架構" tabindex="0" @pointerdown="panStart" @pointermove="panMove" @pointerup="pan=null" @pointercancel="pan=null" @lostpointercapture="pan=null"><p v-if="!loading&&!rows.length">{{units.length?'沒有符合條件的單位':'尚無組織單位，可由新增組織單位開始建立。'}}</p><div :style="{zoom:zoom/100}" class="tree-rows"><div v-for="row in rows" :key="row.unit.id" class="tree-row" @dragover.prevent @drop.prevent.stop="dropUnit(row.unit.id)" :class="{selected:selected===row.unit.id,context:row.context}" :style="{paddingLeft:(12+row.depth*26)+'px'}"><button v-if="row.children" class="toggle" :aria-expanded="!collapsed.has(row.unit.id)||!!search||!!type" :aria-label="'展開或收合 '+row.unit.name" @click="toggle(row.unit.id)">{{collapsed.has(row.unit.id)&&!search&&!type?'＋':'−'}}</button><span v-else class="toggle-spacer"/><button v-if="editing&&row.unit.type!=='company'" type="button" draggable="true" class="drag-handle" :disabled="tab.busy||conflict" :aria-label="'拖曳移動 '+row.unit.name" @dragstart="dragStart($event,row.unit.id)" @dragend="dragging=''">移動</button><button class="unit-button" @click="selected=row.unit.id"><small>{{unitTypes[row.unit.type]}} · {{row.unit.code}}{{row.unit.status==='inactive'?' · 停用':''}}</small><strong>{{row.unit.name}}</strong><span>{{row.unit.members.length}} 位成員 · {{row.unit.managers.map((m:any)=>m.user?.full_name).filter(Boolean).join('、')||'未設定主管'}}</span></button><div v-if="editing" class="hierarchy-fields"><label>上層<select v-model="row.unit.parent_id" :disabled="tab.busy||row.unit.type==='company'||conflict"><option :value="null">無上層</option><option v-for="u in parentOptions(row.unit)" :value="u.id">{{u.name}}</option></select></label><label>排序<input v-model.number="row.unit.sort_order" type="number" min="0" max="1000000" :disabled="tab.busy||conflict"></label></div></div></div></section>
<aside v-if="current" aria-label="單位資料"><p class="eyebrow">{{unitTypes[current.type]}} · {{current.code}}</p><h2>{{current.name}}</h2><p>{{current.status==='active'?'啟用':'停用'}} · 含下層共 {{descendantCount}} 位不重複成員</p><p v-if="current.description" class="description">{{current.description}}</p><div class="actions"><button v-if="caps.update" @click="open()">編輯單位</button><button v-if="caps.members" @click="open('members')">設定成員</button><button v-if="caps.managers" @click="open('managers')">設定主管</button></div><h3>主管（{{current.managers.length}}）</h3><p v-if="!current.managers.length">尚未設定主管</p><p v-for="m in current.managers" :key="m.id">{{m.user?.full_name||m.user?.email}} · {{managerRoles[m.manager_role]}}{{m.is_primary?'（主要）':''}}</p><h3>直接成員（{{current.members.length}}）</h3><p v-if="!current.members.length">尚未設定成員</p><p v-for="m in current.members" :key="m.id"><button v-if="canDrawer&&m.user" class="link" type="button" data-testid="member-link" @click="drawerUser=m.user">{{m.user?.employee_code}} {{m.user?.full_name||m.user?.email}}</button><template v-else>{{m.user?.employee_code}} {{m.user?.full_name||m.user?.email}}</template> <small>{{m.user?.job_title}}</small></p></aside><PersonDrawer v-if="drawerUser&&current" :user="drawerUser" :department-id="current.id" :department-name="current.name" @close="drawerUser=null"/></div>
</template>
<style scoped>
.chart-viewport{padding:12px}.chart-viewport>.notice{border:1px solid #b18b42;background:var(--soft)}.chart-root{display:flex;gap:8px;padding:0;margin:0;align-items:flex-start;min-width:max-content}button.link{border:0;background:none;color:var(--primary);text-decoration:underline;padding:0;min-height:0;text-align:left}.view-switch{display:inline-flex;gap:4px}.root-drop{border:1px dashed var(--primary);padding:16px;margin-bottom:16px;color:var(--primary)}.drag-handle{cursor:grab}.actions,.toolbar,.filters{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.filters{margin:24px 0;align-items:end}.filters>label{display:grid;gap:8px}.filters>label:first-child{flex:1;min-width:220px}.filters .check{display:flex;align-items:center;padding:10px}.check input{width:18px;height:18px;min-width:18px;min-height:18px}.toolbar{margin-bottom:16px}.toolbar label{display:flex;align-items:center;gap:8px;white-space:nowrap}.organization-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px}.tree-viewport{overflow:auto;max-height:70vh;border:1px solid var(--line);touch-action:pan-x pan-y;min-height:200px}.tree-rows{min-width:440px}.tree-row{display:flex;align-items:center;gap:8px;border-bottom:1px solid var(--line);padding:12px}.tree-row.selected{background:var(--soft);border-left:3px solid var(--primary)}.context{opacity:.75}.toggle,.toggle-spacer{width:30px;flex-shrink:0}.toggle{padding:0;min-height:30px}.unit-button{border:0;background:none;text-align:left;display:grid;gap:6px;min-width:210px;flex:1}.unit-button strong{font-size:16px}.unit-button small,.unit-button span,small{color:var(--muted)}.hierarchy-fields{display:flex;gap:8px}.hierarchy-fields label{display:grid;gap:6px}.hierarchy-fields select{width:180px}.hierarchy-fields input{width:80px}aside{border-left:1px solid var(--line);padding-left:24px;overflow-wrap:anywhere}h2{font-size:21px}h3{font-size:16px;margin-top:28px}.description{white-space:pre-wrap}@media(max-width:900px){.organization-layout{grid-template-columns:1fr}aside{border-left:0;border-top:1px solid var(--line);padding:20px 0}.tree-viewport{max-height:55vh}}
</style>
